<?php
require __DIR__.'/bootstrap.php';require_customer();
$q=$db->prepare('SELECT id,name,email FROM customers WHERE id=?');$q->execute([$_SESSION['customer_id']]);$customer=$q->fetch();
if(!$customer){unset($_SESSION['customer_id']);header('Location: login.php');exit;}
$q=$db->prepare('SELECT id,total,status,fulfillment,created_at FROM orders WHERE customer_id=? ORDER BY id DESC LIMIT 100');$q->execute([$customer['id']]);$orders=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My account | The Yummy House</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="top"><a class="brand" href="../index.php">The Yummy House</a><nav class="nav"><a href="../cart.php">Cart</a><form method="post" action="logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button type="submit">Sign out</button></form></nav></header><main class="container"><div class="panel"><h1>Hello, <?=h($customer['name'])?></h1><p class="muted"><?=h($customer['email'])?></p><h2>My orders</h2><?php if(!$orders):?><p>No orders yet. <a href="../index.php#menu">Browse the menu</a>.</p><?php endif;?><?php foreach($orders as $o):?><div class="row" style="border-bottom:1px solid #eadccc;padding:12px 0"><div><strong>Order #<?=(int)$o['id']?></strong><p class="muted"><?=h($o['created_at'])?> · <?=h($o['fulfillment'])?></p></div><div><strong>R<?=number_format($o['total'],2)?></strong><p class="muted"><?=h(ucfirst($o['status']))?></p></div></div><?php endforeach;?></div></main></body></html>
